using System.Reflection;
using System.Text.Json;

namespace Medabots.Rom.Expansion;

/// <summary>
/// What the expansion adds beyond the two source ROMs (generated by tools/export_manifest.py):
/// bots made from scratch (stats + names + the EU bot whose graphics they reuse) and the order and
/// Medapedia names of the Shingata Medarot bots, whose stats and graphics come from that ROM.
/// </summary>
public sealed class ExpansionManifest
{
    private const string ResourceName = "Medabots.Rom.Expansion.expansion.manifest.json";

    public List<ExpansionBot> Bots { get; set; } = [];

    public static ExpansionManifest Default { get; } = Load();

    private static ExpansionManifest Load()
    {
        using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"Missing embedded resource {ResourceName}.");
        return JsonSerializer.Deserialize<ExpansionManifest>(stream, new JsonSerializerOptions { PropertyNameCaseInsensitive = true })
            ?? throw new InvalidDataException("Empty expansion manifest.");
    }
}

public sealed class ExpansionBot
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public List<string> PartNames { get; set; } = [];

    /// <summary>Index in Shingata Medarot (Kabuto); null for bots defined here.</summary>
    public int? ShingataBot { get; set; }

    /// <summary>16 bytes per part (head, right arm, left arm, legs) for bots defined here.</summary>
    public List<List<int>>? Stats { get; set; }

    /// <summary>EU bot whose graphics rows are reused by a bot defined here.</summary>
    public int? GraphicsFrom { get; set; }

    /// <summary>Own colours for reused graphics: "#rrggbb" of the source palettes -> "#rrggbb".</summary>
    public Dictionary<string, string>? Recolor { get; set; }
}
